import json

# Check if CPI data might be in the JSON files
for year in [2001, 2002, 2003]:
    filepath = f"/app/resources/treasury_bulletin_{year}_03.json"
    try:
        with open(filepath, 'r') as f:
            data = json.load(f)

        # Check top-level keys
        print(f"\n=== {year} JSON keys ===")
        if isinstance(data, dict):
            for key in list(data.keys())[:20]:
                print(f"  {key}")
    except Exception as e:
        print(f"Error: {e}")
